{
  "description": "The creature is a large quadrupedal animal shown in right-facing profile that looks like a brown bear in overall body shape, fur texture, and face but with glossy dark beetle-like structures integrated into its body. It is covered in dense shaggy brown fur that is lighter on the muzzle and underside, stands on four thick legs with clawed paws, has a small rounded tail at the rear, a bear-like head with a black nose and brown eyes, a single large curved glossy black horn on its forehead, a large shiny dark dome on the back of its neck and shoulders, dark bands around its lower legs and ankles, and rows of dark oval slit-like openings set into the fur along its sides and limbs.",
  "parts": [
    {
      "part": "head",
      "looks_like": "a bear's head with dense brown fur, a lighter tan muzzle, a large black nose, small brown eyes, and a closed mouth",
      "where": "at the front of the body facing to the right"
    },
    {
      "part": "horns",
      "looks_like": "a single large glossy black horn that curves upward and backward, with a forked tip and small pointed projections along its inner curve, with a shiny bulbous base",
      "where": "emerging from the center of the forehead between the ears on top of the head"
    },
    {
      "part": "ears",
      "looks_like": "two small rounded ears covered in fluffy brown fur",
      "where": "on top of the head behind and to either side of the horn base"
    },
    {
      "part": "legs",
      "looks_like": "four thick sturdy legs covered in long shaggy brown fur, with the forelegs under the chest and hind legs under the hips",
      "where": "supporting the body from below, two in front and two in back"
    },
    {
      "part": "feet",
      "looks_like": "four broad paws with thick fur and long light tan claws on the toes",
      "where": "at the bottom ends of each leg in contact with the ground"
    },
    {
      "part": "tail",
      "looks_like": "a very small short rounded tuft of brown fur",
      "where": "at the extreme rear of the body on the rump"
    },
    {
      "part": "shell",
      "looks_like": "a large glossy dark reddish-black domed beetle-like pronotum/elytra shield with a smooth reflective surface",
      "where": "on the back of the neck and upper shoulders behind the head"
    },
    {
      "part": "plates",
      "looks_like": "glossy dark black transverse bands and small bead-like segments that look like beetle exoskeleton, including bands encircling the lower forelegs, hind legs and ankles and a line of small rounded plates along the spine and around the lower neck",
      "where": "encircling the mid and lower parts of all four legs, around the ankles, along the midline of the back from shoulders to hips, and in a collar around the throat"
    },
    {
      "part": "markings",
      "looks_like": "rows of dark oval slit-like openings with dark interiors set into the fur, resembling spiracles or elytra edges",
      "where": "in a long row along the lower side of the torso, in short diagonal rows on the upper hind leg and rump, and in small clusters on the front and back of the forelegs and on the lower hind legs"
    }
  ],
  "attached_objects": [],
  "animals": [
    "bear",
    "beetle"
  ],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 0,
  "tails": 1
}
